namespace WebSearchShortcut.Helpers;

/// <summary>
/// Images for the settings page cards, as data URIs: the cards are rendered by Command Palette, which can't load
/// files from the extension's package. Generated from PNGs; regenerate rather than editing by hand.
/// </summary>
internal static class CardImages
{
    /// <summary>On/off switch (40x20, drawn at 2x). Adaptive Cards has no switch that acts when flipped, so the card
    /// shows one of these with a submit action.</summary>
    public const string SwitchOn = "data:image/png;base64,";

    /// <summary>See <see cref="SwitchOn"/>.</summary>
    public const string SwitchOff = "data:image/png;base64,";

    /// <summary>Expander chevrons (16x16, drawn at 2x), like Command Palette's own settings expanders.</summary>
    public const string ChevronDown = "data:image/png;base64,";

    /// <summary>See <see cref="ChevronDown"/>.</summary>
    public const string ChevronUp = "data:image/png;base64,";

    /// <summary>Assets/SearchAdd.png.</summary>
    public const string Add = "data:image/png;base64,";

    /// <summary>Assets/Search.png.</summary>
    public const string Search = "data:image/png;base64,";

    /// <summary>Import/export card icon.</summary>
    public const string Import = "data:image/png;base64,";
}
